(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zzq-sj-prepa-ped-j9-idesfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zzq-sj-prepa-ped-j9-idesfm\",\n \"titre\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 57,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n   \"sha256\": \"c1e8c2d8402d3b954a7c6fc159ceb6b02b83cb88c53adce6ddd9268aa4b95034\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n     \"slug\": \"prepa-ped-j9-idesfm\",\n     \"pages\": \"\",\n     \"count\": 57,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Pédiatrie\",\n     \"source\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le paludisme est une maladie virale due à des hématozoaires du genre Plasmodium.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le paludisme est une maladie PARASITAIRE (et non virale) due à un hématozoaire du genre Plasmodium, transmis par l'anophèle femelle. Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Paludisme de l'enfant », Définition\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le vecteur de la maladie est Plasmodium falciparum.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le vecteur est l'anophèle femelle (moustique) ; Plasmodium falciparum est le parasite (agent pathogène). Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Paludisme de l'enfant », Définition ; Les 12 pratiques familiales essentielles (PFE), PFE n° 8\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Plasmodium falciparum est l'espèce responsable des formes graves du paludisme.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Parmi les espèces de Plasmodium, seul P. falciparum est responsable des formes graves du paludisme.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Paludisme de l'enfant », Définition\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le cycle exo-érythrocytaire se fait au niveau des globules rouges.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cycle exo-érythrocytaire (hépatique) se déroule dans le foie ; c'est le cycle érythrocytaire qui se fait dans les globules rouges. Faux. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En salle de naissance, pour décider de la réanimation d'un nouveau-né, le principal élément à évaluer est sa respiration.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale retient « Faux » : la conduite de la réanimation se base sur l'évaluation globale de la vitalité (score d'Apgar : respiration, fréquence cardiaque, tonus, coloration…).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Réanimation du nouveau-né en salle de naissance », Conduite de la réanimation\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La souffrance néonatale est un facteur favorisant des crises convulsives.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale retient « Faux ».\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Convulsions de l'enfant », Facteurs favorisants\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Vous faites une injection de paracétamol en cas d'hyperthermie chez l'enfant de moins de 5 ans. Est-ce un soin propre à l'agent de santé ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le paracétamol injectable est prescrit par le médecin : son injection est un soin délégué (exécuté sur instruction du médecin), pas un soin propre. Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Plan de soins », Interventions – soins délégués / soins propres\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La maladie des membranes hyalines (déficit en surfactant) est une cause fréquente de détresse respiratoire chez le nouveau-né à terme.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La maladie des membranes hyalines (déficit en surfactant) est une maladie du prématuré ; chez le nouveau-né à terme, elle ne se voit guère qu'en cas de mère diabétique ou de césarienne avant terme. Faux.\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre V « Détresse respiratoire néonatale », Maladie des membranes hyalines\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lors de la réanimation du nouveau-né en salle d'accouchement, l'aspiration débute par l'aspiration des fosses nasales avant l'aspiration de la cavité buccale.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"On aspire d'abord la bouche, puis le nez : aspirer le nez en premier peut provoquer un réflexe d'inspiration et l'inhalation du liquide présent dans la bouche. Faux.\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre III « Réanimation en salle de naissance », Désobstruction des VAS\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La bradypnée chez le nouveau-né à terme est marquée par une fréquence respiratoire supérieure à 60 cycles par minute.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Une fréquence respiratoire supérieure à 60 cycles/min est une polypnée (tachypnée) ; la bradypnée est une FR inférieure à 40 cycles/min. Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Nouveau-né prématuré », Problèmes ; Module de néonatologie (Néonatalogie), Chapitre V, Signes cliniques\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Vous recevez lors de votre garde un nourrisson de 8 mois présentant une température de 38,5 °C. Vous installez le nourrisson sur la table d'examen, vous le déshabillez et vous aérez la salle d'examen. Ces gestes que vous faites sont-ils des soins délégués ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Installer, déshabiller l'enfant et aérer la pièce sont des moyens physiques que l'agent de santé réalise de sa propre initiative : ce sont des soins propres, pas des soins délégués. Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Plan de soins », Interventions ; « Fièvre de l'enfant », Moyens physiques\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La ration alimentaire de l'enfant, c'est le nombre de bols de lait donnés à l'enfant par jour.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La ration alimentaire est la QUANTITÉ d'aliments donnée à l'enfant et répartie au cours de la journée, pas le nombre de bols. Faux.\\n\\nSource : Cours de santé infantile L1 IDE-SFM, Diététique – « La ration alimentaire du nouveau-né et du nourrisson »\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La ration alimentaire peut être obtenue seulement en tenant compte de l'âge de l'enfant.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La ration peut être calculée selon l'âge OU selon le poids (règle d'Appert). Faux.\\n\\nSource : Cours de santé infantile L1 IDE-SFM, « La ration alimentaire du nouveau-né et du nourrisson »\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La ration alimentaire d'un enfant de J0 à J2 est de 30 ml pour 6 repas.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"De J0 à J2, la ration est de 30 ml par repas, 6 repas par jour.\\n\\nSource : Cours de santé infantile L1 IDE-SFM, « Ration selon l'âge » (tableau)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'allaitement est contraignant ; cependant, le lait maternel est disponible.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le lait maternel est toujours disponible, prêt à être consommé et à bonne température, même si l'allaitement demande du temps à la mère.\\n\\nSource : Les 12 pratiques familiales essentielles (PFE), PFE n° 2 – Avantages pour la famille\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un enfant de 6 kg a une ration alimentaire de 850 g.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Règle d'Appert : ration journalière = poids (g) ÷ 10 + 250. Pour 6000 g : 600 + 250 = 850 g (ml) par jour.\\n\\nSource : Cours de santé infantile L1 IDE-SFM, « Calcul selon le poids : selon la règle d'Appert »\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__16\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La règle d'Appert est utilisée pour obtenir la ration alimentaire d'un enfant dont on ne connaît pas l'âge.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La règle d'Appert calcule la ration à partir du poids ; elle est donc utile quand l'âge n'est pas connu. Remarque : le cours présente surtout Appert comme la méthode qui « répond mieux aux besoins de l'enfant », pas seulement pour l'âge inconnu.\\n\\nSource : Cours de santé infantile L1 IDE-SFM, « Calcul selon le poids : selon la règle d'Appert »\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__17\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pendant l'examen du nouveau-né, il faut rechercher les réflexes archaïques, au nombre de 7.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours de santé infantile retient 5 réflexes archaïques (succion-déglutition, grasping, points cardinaux, Moro, redressement-marche automatique), pas 7. Faux. Remarque : le module de néonatologie en décrit davantage (allongement croisé, Landau, enjambement…).\\n\\nSource : Cours de santé infantile L1 IDE-SFM, « Examen du nouveau-né en salle de naissance », Réflexes archaïques\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__18\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les soins ombilicaux à la chlorhexidine sont ceux recommandés en Côte d'Ivoire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"En Côte d'Ivoire, l'antiseptique retenu pour les soins du cordon est la chlorhexidine (gel).\\n\\nSource : Cours de santé infantile L1 IDE-SFM, « Soins ombilicaux », Introduction\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__19\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les soins ombilicaux à la chlorhexidine, il n'est pas nécessaire de faire un pansement.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Avec la chlorhexidine gel, on applique le produit sur le cordon (pointe, moignon, base) une fois par jour, et le cordon reste à l'air : le matériel ne comprend pas de compresse de pansement. (explication partiellement hors cours du projet)\\n\\nSource : Cours de santé infantile L1 IDE-SFM, « Soins ombilicaux », Matériel et Technique de soins\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__20\",\n       \"num\": \"21\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'examen du nouveau-né en salle de naissance permet de déceler et corriger les anomalies susceptibles d'entraver ou d'influencer son développement harmonieux.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'examen du nouveau-né est l'ensemble des gestes destinés à déceler (et prendre en charge) les anomalies susceptibles d'influencer son développement harmonieux.\\n\\nSource : Cours de santé infantile L1 IDE-SFM, « Examen du nouveau-né en salle de naissance », Définition\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les facteurs favorisant les intoxications aiguës chez l'enfant sont les suivants sauf un, lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Bas niveau socio-économique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ignorance des parents\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Âge > 7 ans\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Manque de surveillance de l'enfant\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Âge > 7 ans\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les intoxications surviennent surtout avant 5 ans (1-5 ans), favorisées par l'ignorance, le manque de surveillance et le bas niveau socio-économique. L'âge supérieur à 7 ans n'est pas un facteur favorisant.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Intoxications de l'enfant », Facteurs favorisants\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les problèmes posés par l'intoxication chez l'enfant sont (cochez les bonnes réponses) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La détresse respiratoire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La fièvre\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les convulsions\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'anémie aiguë\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. La détresse respiratoire ; C. Les convulsions\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Les principaux problèmes d'une intoxication sont les convulsions, la détresse respiratoire, l'insuffisance hépatique et rénale, la perforation digestive.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Intoxications de l'enfant », Problèmes\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les facteurs ci-dessous sont des facteurs environnementaux de l'asthme sauf un, lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Exposition aux allergènes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Asthme chez les parents\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Tabagisme passif\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Occidentalisation du mode de vie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Asthme chez les parents\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'asthme chez les parents est un facteur intrinsèque (génétique, atopie familiale) ; allergènes, tabagisme passif et mode de vie sont des facteurs extrinsèques (environnementaux).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Asthme de l'enfant », Facteurs étiologiques\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les mécanismes en jeu au cours de l'asthme sont les suivants (cochez les bonnes réponses) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'obstruction\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La saturation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'inflammation\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La vasoconstriction\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. L'obstruction ; C. L'inflammation\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Au cours de l'asthme, trois anomalies sont combinées : l'obstruction (bronchoconstriction), l'inflammation de la paroi bronchique et l'hypersécrétion bronchique.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Asthme de l'enfant », Pathogénie\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les complications à long terme de l'asthme sont (cochez la ou les bonnes réponses) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le retard scolaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La pneumonie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'insuffisance respiratoire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La tuberculose\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. L'insuffisance respiratoire\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La correction nationale retient l'insuffisance respiratoire chronique. Remarque : l'énoncé dit « cochez la ou les bonnes réponses », mais le sujet propose des ronds (une seule réponse).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Asthme de l'enfant », Problèmes et devenir\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les facteurs de risque de la maladie hémorragique du nouveau-né sont les suivants sauf 2, lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hépatite aiguë\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hypotrophie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Certains médicaments\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Asphyxie périnatale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Hépatite aiguë ; B. Hypotrophie\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale retient « hépatite aiguë » et « hypotrophie » comme non-facteurs.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Maladie hémorragique du nouveau-né », Facteurs étiologiques\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher parmi ces signes ceux en rapport avec un nouveau-né post-terme :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Crâne dur\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Petit poids de naissance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Ongles longs\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Teint rouge vif\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Peau desquamante\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Présence de lanugo\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Crâne dur ; B. Petit poids de naissance ; C. Ongles longs ; E. Peau desquamante\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Le post-terme avec signes de post-maturité a un poids souvent diminué, une peau fripée qui desquame, des ongles longs et cassants (teintés de méconium) et des os du crâne durs. Le lanugo et le teint rouge vif sont des signes du prématuré. (explication partiellement hors cours du projet) Remarque : le crâne dur n'est pas cité dans le cours (connaissance générale).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Nouveau-né post terme », Diagnostic positif – En résumé\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les situations à risque de détresse respiratoire chez le nouveau-né sont les suivantes sauf une, laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Souffrance cérébrale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Nouveau-né de mère asthmatique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Prématurité\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Malformation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Nouveau-né de mère asthmatique\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les situations à risque de détresse respiratoire sont liées au fœtus (prématurité, malformation, souffrance cérébrale, hypotrophie, mère diabétique…) ou à la mère/l'accouchement. L'asthme maternel n'est pas cité.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Détresse respiratoire du nouveau-né », Situations à risque\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours de la réanimation d'un nouveau-né en salle de naissance, il y a des gestes à proscrire, lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Aspirer la cavité buccale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Couper le cordon ombilical\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Taper sur les fesses du bébé\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Pincer le mamelon\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Taper sur les fesses du bébé ; D. Pincer le mamelon\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Les gestes brutaux sont à proscrire : tape vigoureuse sur les fesses, friction forte de la peau, pincer le mamelon. Aspirer la bouche et couper le cordon sont des gestes normaux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Réanimation du nouveau-né en salle de naissance », Gestes dangereux à proscrire\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les facteurs ci-dessous, quels sont ceux qui favorisent la survenue d'une otite moyenne aiguë chez l'enfant ? Cochez la bonne réponse.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La rougeole\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La saison des pluies\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La malnutrition\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les rhinites\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Les rhinites\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La correction nationale retient les rhinites (la rhinopharyngite se complique souvent d'otite).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Otite de l'enfant », Facteurs favorisants liés à l'enfant\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les signes cliniques suivants sont ceux de l'otite moyenne aiguë de l'enfant sauf un, lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les ganglions\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'otorrhée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La fièvre\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La rhinite\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. La rhinite\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Les signes de l'OMA sont fièvre, pleurs incessants, otalgie, troubles digestifs et otorrhée. La rhinite n'est pas un signe de l'otite elle-même (elle peut l'accompagner ou la précéder). Remarque : les ganglions cervicaux sont plutôt un signe de rhinopharyngite que d'otite.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Otite de l'enfant », Circonstances de découverte ; « Infections respiratoires aiguës », Otites moyennes aiguës\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les symptômes de la rhinopharyngite aiguë sont (cochez les réponses justes) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La toux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les céphalées\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La rhinorrhée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La fièvre\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Les céphalées ; C. La rhinorrhée ; D. La fièvre\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"La rhinopharyngite donne fièvre, rhinorrhée (claire ou purulente), obstruction nasale et douleur de gorge. La toux doit faire craindre une atteinte des voies respiratoires basses. Remarque : les céphalées ne sont pas citées dans le cours.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Rhinopharyngite de l'enfant », Arguments anamnestiques\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nouveau-né hypotrophe est un nouveau-né (entourez la bonne réponse) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"dont le poids est inférieur à l'âge\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"de petit poids de naissance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"né à terme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. dont le poids est inférieur à l'âge\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le nouveau-né hypotrophe est né à terme mais avec un poids de naissance inférieur à la normale pour son âge gestationnel (< 2500 g). « Petit poids de naissance » s'applique aussi au prématuré et n'est donc pas spécifique.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Nouveau-né hypotrophe », Définition\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Ces signes sont en rapport avec l'hypotrophe sauf un, lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Membres grêles\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Retard pondéral\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Peau fripée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Somnolence\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Somnolence\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'hypotrophe a une peau fripée, des membres grêles, une maigreur, un regard vif et un retard pondéral. La somnolence n'en fait pas partie (regard vif, enfant éveillé).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Nouveau-né hypotrophe », Informations à rechercher à l'examen physique\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le post-terme est un nouveau-né (entourez les réponses fausses) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"né après 36 SA + 6 j\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"né après 42 SA\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"de petit poids de naissance\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"dont le poids est insuffisant par rapport à l'âge\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. né après 42 SA\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale retient « né après 42 SA ».\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Nouveau-né post terme », Définition\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__36\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Vous recevez le nourrisson TD âgé de 14 mois. Lors de l'évaluation de son état nutritionnel, vous trouvez que TD a une malnutrition aiguë sévère. Son Z-score poids/taille est donc de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"0 < Z-score < −1\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"−1 < Z-score < −2\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Z-score < −3\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"−2 < Z-score < −3\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Z-score < −3\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La malnutrition aiguë sévère correspond à un Z-score poids/taille inférieur à −3 (modérée : entre −3 et −2).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Malnutrition de l'enfant », Classification de la malnutrition aiguë sévère\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__37\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un nourrisson de 13 mois qui a une malnutrition aiguë sévère compliquée d'œdème et d'infection pulmonaire sera (cochez la réponse exacte) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Pris en charge avec des aliments thérapeutiques prêts à l'emploi (ATPE) en ambulatoire (en communauté)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Pris en charge avec du lait F75, du lait F100 et des ATPE en milieu hospitalier\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Pris en charge avec des ATPE uniquement et en milieu hospitalier\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Pris en charge avec du lait F75, du lait F100 et des ATPE en ambulatoire (en communauté)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Pris en charge avec du lait F75, du lait F100 et des ATPE en milieu hospitalier\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Une malnutrition aiguë sévère avec complications (œdèmes, infection respiratoire…) est prise en charge en unité de nutrition thérapeutique (hôpital) avec F75, puis F100, puis ATPE.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Malnutrition de l'enfant », Classification de la malnutrition aiguë sévère (tableau) ; Réhabilitation nutritionnelle\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__38\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La rhinopharyngite est fréquente chez le nourrisson. Le germe le plus rencontré dans cette affection est (choisissez la réponse exacte) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Parasite\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Bactérie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Champignon\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Virus\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Virus\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Les germes de la rhinopharyngite sont surtout des virus (rhinovirus, VRS, para-influenzae…) ; les bactéries interviennent en cas de surinfection.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Rhinopharyngite de l'enfant », Germes\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__39\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lors de la prise en charge d'un nourrisson présentant une staphylococcie pleuropulmonaire, vous injectez des antibiotiques. Quel est le type de soin que vous exécutez dans ce cas ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Soins de collaboration\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Soins délégués\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Soins propres\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Soins préventifs\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Soins délégués\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'injection d'antibiotiques prescrits par le médecin est un soin délégué (exécuté sur instruction du médecin).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Plan de soins », Interventions – soins délégués\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__40\",\n       \"num\": \"41\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'anémie du nouveau-né peut être due à des prélèvements itératifs. Cette pratique est un facteur favorisant lié à (choisissez la réponse correcte) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"la mère\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"l'enfant\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"l'agent de santé\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"la communauté\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. l'agent de santé\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les prélèvements sanguins répétés (itératifs) sont une cause d'anémie du nouveau-né liée aux soins : c'est un facteur lié à l'agent de santé ; le cours recommande de limiter les prélèvements.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Anémie aiguë de l'enfant », Principales causes ; Module de néonatologie (Néonatalogie), Chapitre VIII, Anémie du prématuré\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__41\",\n       \"num\": \"42\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Devant une anémie chez l'enfant, vous prélevez du sang pour des examens de laboratoire. Quel est le type de soin que vous avez exécuté ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Soins préventifs\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Soins de collaboration\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Soins délégués\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Soins propres\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Soins délégués\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Faire un prélèvement sanguin pour les examens prescrits est cité comme exemple de soin délégué.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Plan de soins », Interventions – soins délégués\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__42\",\n       \"num\": \"43\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour la prévention de la maladie hémorragique du nouveau-né, vous lui injectez un médicament. Identifiez le médicament dans la liste ci-dessous.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vitamine C\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Vitamine D\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Vitamine K\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Vitamine ADEC\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Vitamine K\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La maladie hémorragique est due à une carence en vitamine K1 ; sa prévention repose sur l'injection systématique de vitamine K1 à la naissance.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Maladie hémorragique du nouveau-né », Intérêt\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__43\",\n       \"num\": \"44\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Vous êtes en salle de naissance. Madame KS, âgée de 28 ans, vient d'accoucher de son premier enfant à 39 SA. KS n'a reçu que 2 doses de vaccin antitétanique : la première à 20 SA et la 2e à 38 SA. Que faites-vous au nouveau-né pour la prévention du tétanos néonatal ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vous injectez un vaccin antitétanique au nouveau-né\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Vous injectez du sérum antitétanique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Vous ne faites rien car le nouveau-né est déjà protégé\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Vous injectez un antibiotique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Vous injectez du sérum antitétanique\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La 2e dose de VAT faite à 38 SA, une semaine avant l'accouchement, n'a pas eu le temps de protéger le nouveau-né (il faut au moins 2 semaines). Le nouveau-né n'est pas protégé : on lui injecte du sérum antitétanique (immunité immédiate). (explication partiellement hors cours du projet)\\n\\nSource : Les 12 pratiques familiales essentielles (PFE), PFE n° 6 – Calendrier vaccinal de la femme en âge de reproduction\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__44\",\n       \"num\": \"45\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Ces différents items permettent d'apprécier le score d'APGAR sauf un, lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"R : Respiration (mouvements respiratoires)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"A : Aréflexie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"A : Aspect, couleur de la peau\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"G : Grimace, qualité du cri\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"P : Pouls (fréquence cardiaque)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. A : Aréflexie\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"APGAR = Aspect (couleur), Pouls (FC), Grimace (réactivité), Activité (tonus), Respiration. « Aréflexie » n'est pas un item. Remarque : dans le sujet, l'option « Aspect, couleur de la peau » n'a pas de lettre ; « A : » a été ajouté pour la lisibilité.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Souffrance cérébrale du nouveau-né », Tableau du score d'Apgar\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__45\",\n       \"num\": \"46\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'objectif de la PCIMNE est de contribuer à la réduction de la morbidité et de la mortalité des enfants de moins de 5 ans en s'appuyant sur 3 composantes :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Composante n° 3 : Promotion des pratiques familiales essentielles dans les familles et communautés\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Composante n° 1 : Renforcement du système de santé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Composante n° 2 : Amélioration des compétences des agents de santé\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Composante n° 3 : Promotion des pratiques familiales essentielles dans les familles et communautés\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Composantes de la PCIMNE : n° 1 amélioration des compétences des agents de santé ; n° 2 renforcement du système de santé ; n° 3 promotion des pratiques familiales essentielles. Seule la composante n° 3 est correctement numérotée dans les propositions. Remarque : la question 46 et la question 47 sont la même question dans le sujet, avec les options dans un autre ordre.\\n\\nSource : Cours PCIMNE 2026, diapositive « Objectif (1/7) »\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__46\",\n       \"num\": \"47\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'objectif de la PCIMNE est de contribuer à la réduction de la morbidité et de la mortalité des enfants de moins de 5 ans en s'appuyant sur 3 composantes. Choisir la bonne réponse :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Composante n° 2 : Amélioration des compétences des agents de santé\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Composante n° 3 : Promotion des pratiques familiales essentielles dans les familles et communautés\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Composante n° 1 : Renforcement du système de santé\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Composante n° 3 : Promotion des pratiques familiales essentielles dans les familles et communautés\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Même question : seule « Composante n° 3 : promotion des pratiques familiales essentielles » est juste ; les deux autres ont des numéros inversés.\\n\\nSource : Cours PCIMNE 2026, diapositive « Objectif (1/7) »\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__47\",\n       \"num\": \"48\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les principes de la PCIMNE ci-dessous, choisir la bonne réponse :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Utilisation des signes spéciaux pour la classification de la maladie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Conseiller la mère\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Organiser le quand revenir\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Approche rationnelle pour classer la maladie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Conseiller la mère\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Principes de la PCIMNE : approche syndromique et systématique, signes spécifiques pour classer, approche rationnelle pour le TRAITEMENT, conseiller la mère, organiser la continuité des soins. « Conseiller la mère » est la seule proposition formulée comme dans le cours.\\n\\nSource : Cours PCIMNE 2026, diapositive « Principes »\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__48\",\n       \"num\": \"49\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les signes suivants, un seul fait partie de l'infection bactérienne néonatale grave. Lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Stridor\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ombilic rouge\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Incapable de s'alimenter\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hypothermie modérée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Incapable de s'alimenter\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'incapacité à s'alimenter fait partie des signes d'infection bactérienne grave du nouveau-né. Une hypothermie modérée et un ombilic rouge (non étendu) relèvent d'autres classifications ; le stridor concerne l'enfant plus grand.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans, Tableau du nouveau-né « Infection bactérienne grave »\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__49\",\n       \"num\": \"50\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nouveau-né est bien tenu par la mère lors de la tétée lorsque (choisir la mauvaise réponse) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le nouveau-né fait face au sein, son nez en face du mamelon\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La tête et le corps du nouveau-né sont dans le même axe\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La mère doit soutenir seulement le corps et les épaules du nouveau-né\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le corps du nouveau-né doit être proche du corps de la mère\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. La mère doit soutenir seulement le corps et les épaules du nouveau-né\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Bonne position : tête et corps droits dans le même axe, visage face au sein et nez face au mamelon, corps proche de la mère, et TOUT le corps soutenu par la mère (s'il s'agit d'un nouveau-né). Soutenir seulement le corps et les épaules est la mauvaise réponse.\\n\\nSource : Les 12 pratiques familiales essentielles (PFE), PFE n° 2 – Bonne position de l'enfant au sein\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__50\",\n       \"num\": \"51\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les principales causes de mortalité dans la PCIMNE sont (choisir la mauvaise réponse) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La malnutrition\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le tétanos néonatal\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La rougeole\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le paludisme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Le tétanos néonatal\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les 7 principales causes de mortalité visées par la PCIMNE sont : affections néonatales graves, paludisme, IRA, diarrhée, rougeole, malnutrition, VIH/sida. Le tétanos néonatal n'est pas cité en tant que tel.\\n\\nSource : Cours PCIMNE 2026, diapositive « Stratégie (3/3) »\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__51\",\n       \"num\": \"52\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le lait maternel est un aliment complet (choisir la mauvaise réponse) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Il rend intelligent\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Il est facile à digérer\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Il protège contre les affections\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Il contient des éléments nutritifs idéaux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Il protège contre les affections\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La correction nationale retient « Il protège contre les affections » comme mauvaise réponse.\\n\\nSource : Les 12 pratiques familiales essentielles (PFE), PFE n° 2 – Avantages pour le bébé\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__52\",\n       \"num\": \"53\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les réponses ci-dessous, une seule est un avantage pour la mère de l'allaitement maternel exclusif, lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Moins de dépenses en frais médicaux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"C'est un aliment complet\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Réduit le risque de cancer de l'utérus\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Relation affective entre la mère et le bébé\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Relation affective entre la mère et le bébé\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Pour la mère, l'allaitement crée une relation intime et affective avec le bébé (et réduit le risque de cancer des ovaires et du SEIN, pas de l'utérus). « Moins de dépenses médicales » est un avantage pour le père, « aliment complet » un avantage pour le bébé.\\n\\nSource : Les 12 pratiques familiales essentielles (PFE), PFE n° 2 – Avantages de l'AME pour la mère\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__53\",\n       \"num\": \"54\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Ce schéma représente les stries plantaires d'un nouveau-né. Choisir les bonnes réponses :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Nouveau-né à terme eutrophe\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Nouveau-né à terme hypotrophe\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Nouveau-né prématuré hypotrophe\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Nouveau-né prématuré\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Nouveau-né à terme eutrophe\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Sur le schéma, les stries plantaires couvrent toute la plante du pied : c'est un critère de maturité du nouveau-né à terme. Chez le prématuré, les stries sont absentes ou limitées à l'avant du pied. (explication partiellement hors cours du projet)\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Photothèque « Nouveau-né à terme » / « Nouveau-né prématuré à J0 » (stries plantaires)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__54\",\n       \"num\": \"55\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours d'une séance de CCC pendant la grossesse, vous citez les facteurs favorisant la prématurité aux parturientes. L'une de ces propositions est fausse, laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Fatigue liée au travail professionnel ou familial\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Multiparité\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Âge > 18 ans et < 35 ans\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Tabagisme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Âge > 18 ans et < 35 ans\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le jeune âge (< 18 ans) et l'âge avancé (> 35 ans) sont des facteurs favorisants de prématurité ; un âge entre 18 et 35 ans n'en est pas un. Fatigue, multiparité et tabac sont des facteurs favorisants.\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre VIII « Prématurité », Facteurs individuels et psycho-sociaux\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__55\",\n       \"num\": \"56\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour la sécurité d'un accouchement prématuré, il faut (choisir la ou les bonnes réponses) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une personne\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une bonne chaîne de froid\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Asepsie rigoureuse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Aspiration douce si nécessaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Asepsie rigoureuse ; D. Aspiration douce si nécessaire\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"L'accouchement prématuré exige une asepsie rigoureuse (risque infectieux élevé) et une aspiration douce si nécessaire. Il faut au moins deux personnes formées, et c'est la chaîne du CHAUD (et non du froid) qui doit être assurée.\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre VIII « Prématurité », Prise en charge – En salle de naissance ; Chapitre XIX, Chaîne du chaud\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j9-idesfm__56\",\n       \"num\": \"57\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Concernant l'hypotrophie (ou RCIU) harmonieuse, choisir les réponses fausses :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La cause est tardive\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le poids, la taille et le périmètre crânien sont toujours diminués\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Seuls le poids et la taille sont diminués\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La peau est fripée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Seuls le poids et la taille sont diminués\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Dans l'hypotrophie harmonieuse, poids, taille ET périmètre crânien sont diminués ; « seuls le poids et la taille sont diminués » décrit la forme dysharmonieuse : c'est donc une réponse fausse. Remarque : la capture s'arrête au bas de cette question ; une 5e option éventuelle n'est pas visible dans le sujet. CORRIGÉ EXPLIQUÉ — PRÉPA DE INFAS\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Nouveau-né hypotrophe », Introduction (hypotrophe harmonieux / dysharmonieux)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J9 (IDE-SF-M)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
